    name = EXCLUDED.name, py_str = EXCLUDED.py_str, type_enum = EXCLUDED.type_enum,
    status_enum = EXCLUDED.status_enum, pricing_flag = EXCLUDED.pricing_flag,
    permitted_gender_enum = EXCLUDED.permitted_gender_enum,
